"""Verifier for dense-department-budgets. Generated by scripts/build_harbor_tasks.py.

S1 cheap artifact checks, S2 content checks on the manifest of a re-run of
plot.py, S3 delivered PNG == fresh render, S5 sidecar against the answer key.
Machinery: verifier_core.py (adapted from harbor/example/tests/test_state.py).

Known blind spots (the point of the second mutant): nothing here measures
legibility -- tick-label rotation, overlap, clipping at the image edge, or
contrast -- and line dash patterns and legend placement are only partly checked.
"""

from pathlib import Path

import pytest

from verifier_core import (
    APP, DELIVERED_FIGURE, assert_close, axes, bar_containers, check_input_unchanged,
    check_rerender_matches, check_valid_nonblank_png, delivered, find_script, lines,
    load_sidecar, norm_colour, snapshot_delivered, reexecute,
)

INPUTS = {}


@pytest.fixture(scope="session")
def manifest():
    snapshot_delivered()
    return reexecute(Path("/tmp/reexec"))


def test_s1_figure_is_a_valid_nonblank_png():
    snapshot_delivered()
    check_valid_nonblank_png()


def test_s1_inputs_unchanged():
    for name, digest in INPUTS.items():
        check_input_unchanged(name, digest)


def test_s1_plotting_script_left_behind():
    assert find_script().stat().st_size > 0


def test_s3_delivered_png_matches_a_fresh_render(manifest):
    check_rerender_matches(manifest)


def png_size():
    from PIL import Image

    with Image.open(delivered(DELIVERED_FIGURE)) as image:
        return image.size

NAMES = ["Department of Transportation and Infrastructure", "Ministry of Health and Long-Term Care", "Office of the Auditor General", "Department of Fisheries and Oceans", "Ministry of Education and Child Care", "Agency for Environmental Protection", "Department of Finance and Treasury Board", "Office of Indigenous Relations", "Ministry of Labour and Workforce Development", "Department of Agriculture and Agri-Food", "Office of the Chief Information Officer", "Ministry of Housing and Municipal Affairs", "Department of Justice and Public Safety", "Agency for Statistics and Data Services", "Ministry of Energy, Mines and Low Carbon Innovation", "Department of Tourism, Arts and Culture", "Office of the Ombudsperson", "Ministry of Forests and Range Management", "Department of Veterans Affairs", "Agency for Emergency Management", "Ministry of Post-Secondary Education and Skills", "Department of Public Works and Procurement", "Office of the Information and Privacy Commissioner", "Ministry of Citizens' Services", "Department of Trade and Investment", "Agency for Water Stewardship", "Ministry of Social Development and Poverty Reduction", "Department of Northern Affairs", "Office of the Seniors Advocate", "Ministry of Mental Health and Addictions"]
VALUES = [114, 240, 742, 427, 398, 101, 631, 585, 246, 769, 198, 851, 22, 328, 763, 118, 162, 398, 701, 584, 181, 254, 283, 635, 725, 885, 620, 390, 278, 475]


def test_s5_sidecar_matches_key():
    declared = load_sidecar()
    assert sorted(declared) == ["budgets_k", "departments"], f"sidecar keys {sorted(declared)}"
    assert declared["departments"] == NAMES, "department names or order differ"
    assert_close(declared["budgets_k"], VALUES, 1e-9, "budgets_k")


def test_s2_thirty_bars_in_the_given_order(manifest):
    bars = [c for c in bar_containers(manifest) if c.get("orientation") == "vertical"]
    offsets = [o for c in bars for o in c["offsets"]]
    values = [v for c in bars for v in c["values"]]
    assert_close([v for _, v in sorted(zip(offsets, values))], VALUES, 1e-9, "bar heights left to right")


def test_s2_full_names_as_tick_labels(manifest):
    labels = [t for t in axes(manifest)["xticklabels"] if t.strip()]
    assert labels == NAMES, "x tick labels are not the 30 full department names in order"


def test_s2_axes_text_and_limits(manifest):
    ax = axes(manifest)
    assert ax["ylabel"] == "IT budget (thousand $)"
    assert ax["title"] == "IT budget by department"
    assert abs(ax["ylim"][0]) < 1e-9, f"y axis starts at {ax['ylim'][0]}"


def test_s2_figure_is_12_by_6_inches_at_100_dpi():
    assert png_size() == (1200, 600), f"figure.png is {png_size()}, expected 1200x600"
